package com.itu.gestionRH.entity.organization; import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="DEMANDE_CONGE") public class DemandeConge{@Id @GeneratedValue(strategy=GenerationType.SEQUENCE,generator="demandeConge") @SequenceGenerator(name="demandeConge",sequenceName="SEQ_DEMANDE_CONGE",allocationSize=1) Long id; @ManyToOne @JoinColumn(name="EMPLOYE_ID") Employe employe; String typeConge; LocalDate dateDebut,dateFin; double joursDemandes; String motif,statut="EN_ATTENTE",commentaireValidation; @ManyToOne @JoinColumn(name="VALIDATEUR_ID") Employe validateur; LocalDateTime dateValidation; public Long getId(){return id;} public Employe getEmploye(){return employe;} public void setEmploye(Employe v){employe=v;} public String getTypeConge(){return typeConge;} public void setTypeConge(String v){typeConge=v;} public LocalDate getDateDebut(){return dateDebut;} public void setDateDebut(LocalDate v){dateDebut=v;} public LocalDate getDateFin(){return dateFin;} public void setDateFin(LocalDate v){dateFin=v;} public double getJoursDemandes(){return joursDemandes;} public void setJoursDemandes(double v){joursDemandes=v;} public String getMotif(){return motif;} public void setMotif(String v){motif=v;} public String getStatut(){return statut;} public void setStatut(String v){statut=v;} public Employe getValidateur(){return validateur;} public void setValidateur(Employe v){validateur=v;} public LocalDateTime getDateValidation(){return dateValidation;} public void setDateValidation(LocalDateTime v){dateValidation=v;} public String getCommentaireValidation(){return commentaireValidation;} public void setCommentaireValidation(String v){commentaireValidation=v;} }
